CREATE TABLE "Company" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "type" TEXT NOT NULL, "taxNumber" TEXT, "phone" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "Company_name_key" ON "Company"("name");
CREATE TABLE "Sector" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "companyId" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "Sector_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Sector_name_companyId_key" ON "Sector"("name", "companyId");
CREATE TABLE "Project" ("id" TEXT NOT NULL PRIMARY KEY, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "companyId" TEXT NOT NULL, "sectorId" TEXT, "status" TEXT NOT NULL DEFAULT 'ACTIVE', "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "Project_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "Project_sectorId_fkey" FOREIGN KEY ("sectorId") REFERENCES "Sector"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Project_code_key" ON "Project"("code");
CREATE TABLE "Employee" ("id" TEXT NOT NULL PRIMARY KEY, "employeeCode" TEXT NOT NULL, "name" TEXT NOT NULL, "jobTitle" TEXT NOT NULL, "phone" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "Employee_employeeCode_key" ON "Employee"("employeeCode");
CREATE TABLE "ProjectEngineerAssignment" ("id" TEXT NOT NULL PRIMARY KEY, "projectId" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "startDate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "endDate" DATETIME, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ProjectEngineerAssignment_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "ProjectEngineerAssignment_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "ProjectEngineerAssignment_projectId_employeeId_startDate_key" ON "ProjectEngineerAssignment"("projectId", "employeeId", "startDate");
